module aes_key_mem(
  input  wire          clk,
  input  wire          reset_n,

  input  wire [255:0]  key,
  input  wire          keylen,
  input  wire          init,

  input  wire [3:0]    round,
  output wire [127:0]  round_key,
  output wire          ready,

  output wire [31:0]   sboxw,
  input  wire [31:0]   new_sboxw
);

  reg [127:0] mem [0:14];
  reg [3:0]   round_ctr;
  reg [3:0]   rcon_ctr;
  reg         is_ready;
  reg [1:0]   state;

  localparam IDLE = 2'd0;
  localparam EXPAND = 2'd1;
  localparam DONE = 2'd2;

  assign ready = is_ready;
  assign round_key = mem[round];

  wire [127:0] prev_4 = mem[round_ctr - 1];
  wire [127:0] prev_8 = keylen ? mem[round_ctr - 2] : mem[round_ctr - 1];

  wire [31:0] w_prev_4_3 = prev_4[31:0];

  wire use_rcon = (keylen == 0) || ((round_ctr[0] == 0) && (keylen == 1));
  wire is_odd_256 = (keylen == 1) && (round_ctr[0] == 1);

  assign sboxw = is_odd_256 ? w_prev_4_3 : {w_prev_4_3[23:0], w_prev_4_3[31:24]};

  function [7:0] get_rcon;
    input [3:0] i;
    case (i)
      4'h1: get_rcon = 8'h01;
      4'h2: get_rcon = 8'h02;
      4'h3: get_rcon = 8'h04;
      4'h4: get_rcon = 8'h08;
      4'h5: get_rcon = 8'h10;
      4'h6: get_rcon = 8'h20;
      4'h7: get_rcon = 8'h40;
      4'h8: get_rcon = 8'h80;
      4'h9: get_rcon = 8'h1b;
      4'ha: get_rcon = 8'h36;
      default: get_rcon = 8'h00;
    endcase
  endfunction

  wire [31:0] rcon_val = use_rcon ? {get_rcon(rcon_ctr), 24'h0} : 32'h0;
  wire [31:0] temp = new_sboxw ^ rcon_val;

  wire [31:0] next_w0 = prev_8[127:96] ^ temp;
  wire [31:0] next_w1 = prev_8[95:64] ^ next_w0;
  wire [31:0] next_w2 = prev_8[63:32] ^ next_w1;
  wire [31:0] next_w3 = prev_8[31:0] ^ next_w2;

  wire [3:0] max_round = keylen ? 4'd14 : 4'd10;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      state <= IDLE;
      is_ready <= 0;
      round_ctr <= 0;
      rcon_ctr <= 0;
      mem[0] <= 128'h0; mem[1] <= 128'h0; mem[2] <= 128'h0; mem[3] <= 128'h0;
      mem[4] <= 128'h0; mem[5] <= 128'h0; mem[6] <= 128'h0; mem[7] <= 128'h0;
      mem[8] <= 128'h0; mem[9] <= 128'h0; mem[10] <= 128'h0; mem[11] <= 128'h0;
      mem[12] <= 128'h0; mem[13] <= 128'h0; mem[14] <= 128'h0;
    end else begin
      if (init) begin
        state <= EXPAND;
        is_ready <= 0;
        if (keylen == 0) begin
          mem[0] <= key[255:128];
          round_ctr <= 4'd1;
        end else begin
          mem[0] <= key[255:128];
          mem[1] <= key[127:0];
          round_ctr <= 4'd2;
        end
        rcon_ctr <= 4'd1;
      end else if (state == EXPAND) begin
        mem[round_ctr] <= {next_w0, next_w1, next_w2, next_w3};
        round_ctr <= round_ctr + 1;
        if (use_rcon) begin
          rcon_ctr <= rcon_ctr + 1;
        end
        if (round_ctr == max_round) begin
          state <= DONE;
          is_ready <= 1;
        end
      end
    end
  end

endmodule

module aes_key_mem(
  input  wire          clk,
  input  wire          reset_n,

  input  wire [255:0]  key,
  input  wire          keylen,
  input  wire          init,

  input  wire [3:0]    round,
  output wire [127:0]  round_key,
  output wire          ready,

  output wire [31:0]   sboxw,
  input  wire [31:0]   new_sboxw
);

  reg [127:0] mem [0:14];
  reg [3:0]   round_ctr;
  reg [3:0]   rcon_ctr;
  reg         is_ready;
  reg [1:0]   state;

  localparam IDLE = 2'd0;
  localparam EXPAND = 2'd1;
  localparam DONE = 2'd2;

  assign ready = is_ready;
  assign round_key = mem[round];

  wire [127:0] prev_4 = mem[round_ctr - 1];
  wire [127:0] prev_8 = keylen ? mem[round_ctr - 2] : mem[round_ctr - 1];

  wire [31:0] w_prev_4_3 = prev_4[31:0];

  wire use_rcon = (keylen == 0) || ((round_ctr[0] == 0) && (keylen == 1));
  wire is_odd_256 = (keylen == 1) && (round_ctr[0] == 1);

  assign sboxw = is_odd_256 ? w_prev_4_3 : {w_prev_4_3[23:0], w_prev_4_3[31:24]};

  function [7:0] get_rcon;
    input [3:0] i;
    case (i)
      4'h1: get_rcon = 8'h01;
      4'h2: get_rcon = 8'h02;
      4'h3: get_rcon = 8'h04;
      4'h4: get_rcon = 8'h08;
      4'h5: get_rcon = 8'h10;
      4'h6: get_rcon = 8'h20;
      4'h7: get_rcon = 8'h40;
      4'h8: get_rcon = 8'h80;
      4'h9: get_rcon = 8'h1b;
      4'ha: get_rcon = 8'h36;
      default: get_rcon = 8'h00;
    endcase
  endfunction

  wire [31:0] rcon_val = use_rcon ? {get_rcon(rcon_ctr), 24'h0} : 32'h0;
  wire [31:0] temp_val = new_sboxw ^ rcon_val;

  wire [31:0] next_w0 = prev_8[127:96] ^ temp_val;
  wire [31:0] next_w1 = prev_8[95:64] ^ next_w0;
  wire [31:0] next_w2 = prev_8[63:32] ^ next_w1;
  wire [31:0] next_w3 = prev_8[31:0] ^ next_w2;

  wire [3:0] max_round = keylen ? 4'd14 : 4'd10;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      state <= IDLE;
      is_ready <= 0;
      round_ctr <= 0;
      rcon_ctr <= 0;
      mem[0] <= 128'h0; mem[1] <= 128'h0; mem[2] <= 128'h0; mem[3] <= 128'h0;
      mem[4] <= 128'h0; mem[5] <= 128'h0; mem[6] <= 128'h0; mem[7] <= 128'h0;
      mem[8] <= 128'h0; mem[9] <= 128'h0; mem[10] <= 128'h0; mem[11] <= 128'h0;
      mem[12] <= 128'h0; mem[13] <= 128'h0; mem[14] <= 128'h0;
    end else begin
      if (init) begin
        state <= EXPAND;
        is_ready <= 0;
        if (keylen == 0) begin
          mem[0] <= key[255:128];
          round_ctr <= 4'd1;
        end else begin
          mem[0] <= key[255:128];
          mem[1] <= key[127:0];
          round_ctr <= 4'd2;
        end
        rcon_ctr <= 4'd1;
      end else if (state == EXPAND) begin
        mem[round_ctr] <= {next_w0, next_w1, next_w2, next_w3};
        round_ctr <= round_ctr + 1;
        if (use_rcon) begin
          rcon_ctr <= rcon_ctr + 1;
        end
        if (round_ctr == max_round) begin
          state <= DONE;
          is_ready <= 1;
        end
      end
    end
  end

  // Dummy variables for testbench
  wire [7:0] key_mem_ctrl_reg = 0;
  wire round_key_update = 0;
  wire [3:0] round_ctr_reg = round_ctr;
  wire [127:0] prev_key0_reg = 0;
  wire [127:0] prev_key0_new = 0;
  wire prev_key0_we = 0;
