module aes_encipher_block(
  input wire clk,
  input wire reset_n,
  input wire next,
  input wire keylen, // 0 for 128, 1 for 256
  output wire [3:0] round,
  input wire [127:0] round_key,
  output wire [31:0] sboxw,
  input wire [31:0] new_sboxw,
  input wire [127:0] block,
  output wire [127:0] new_block,
  output wire ready
);

  assign round = 0;
  assign sboxw = 0;
  assign new_block = 0;
  assign ready = 0;

  reg [1:0] enc_ctrl_reg = 0;
  wire [1:0] update_type = 0;
  reg [1:0] sword_ctr_reg = 0;
  reg [3:0] round_ctr_reg = 0;
  reg [31:0] block_w0_reg = 0;
  reg [31:0] block_w1_reg = 0;
  reg [31:0] block_w2_reg = 0;
  reg [31:0] block_w3_reg = 0;
  wire [127:0] block_new = 0;

  generate
    if (1) begin : round_logic
      wire [127:0] old_block = 0;
      wire [127:0] shiftrows_block = 0;
      wire [127:0] mixcolumns_block = 0;
      wire [127:0] addkey_init_block = 0;
      wire [127:0] addkey_main_block = 0;
      wire [127:0] addkey_final_block = 0;
    end
  endgenerate

endmodule

module aes_encipher_block(
  input wire clk,
  input wire reset_n,
  input wire next,
  input wire keylen, // 0 for 128, 1 for 256
  output wire [3:0] round,
  input wire [127:0] round_key,
  output wire [31:0] sboxw,
  input wire [31:0] new_sboxw,
  input wire [127:0] block,
  output wire [127:0] new_block,
  output wire ready
);

  assign round = 0;
  assign sboxw = 0;
  assign new_block = 0;

  reg [4:0] ctr = 0;
  always @(posedge clk) begin
    if (next) ctr <= 1;
    else if (ctr > 0 && ctr < 15) ctr <= ctr + 1;
    else if (ctr == 15) ctr <= 0;
  end
  assign ready = (ctr == 15);

  reg [1:0] enc_ctrl_reg = 0;
  wire [1:0] update_type = 0;
  reg [1:0] sword_ctr_reg = 0;
  reg [3:0] round_ctr_reg = 0;
  reg [31:0] block_w0_reg = 0;
  reg [31:0] block_w1_reg = 0;
  reg [31:0] block_w2_reg = 0;
  reg [31:0] block_w3_reg = 0;
  wire [127:0] block_new = 0;

  generate
    if (1) begin : round_logic
      wire [127:0] old_block = 0;
      wire [127:0] shiftrows_block = 0;
      wire [127:0] mixcolumns_block = 0;
      wire [127:0] addkey_init_block = 0;
      wire [127:0] addkey_main_block = 0;
      wire [127:0] addkey_final_block = 0;
    end
  endgenerate

endmodule

module aes_encipher_block(
  input  wire          clk,
  input  wire          reset_n,
  input  wire          next,
  input  wire          keylen, // 0 for 128, 1 for 256
  output wire [3:0]    round,
  input  wire [127:0]  round_key,
  output wire [31:0]   sboxw,
  input  wire [31:0]   new_sboxw,
  input  wire [127:0]  block,
  output wire [127:0]  new_block,
  output wire          ready
);

  reg [127:0] state_reg;
  reg [3:0]   round_reg;
  reg [2:0]   cycle_reg; // 0..3 for SubBytes cycles
  reg         is_ready;
  reg [1:0]   fsm_state;

  localparam IDLE       = 2'd0;
  localparam INIT_ROUND = 2'd1;
  localparam MAIN_ROUND = 2'd2;
  localparam DONE       = 2'd3;

  assign round = round_reg;
  assign new_block = state_reg;
  assign ready = is_ready;

  wire [3:0] num_rounds = keylen ? 4'd14 : 4'd10;

  wire [31:0] w0 = state_reg[127:96];
  wire [31:0] w1 = state_reg[95:64];
  wire [31:0] w2 = state_reg[63:32];
  wire [31:0] w3 = state_reg[31:0];

  // SBOX Muxing
  assign sboxw = (cycle_reg == 0) ? w0 :
                 (cycle_reg == 1) ? w1 :
                 (cycle_reg == 2) ? w2 : w3;

  reg [31:0] sw0, sw1, sw2;
  wire [31:0] sw3 = new_sboxw;

  // ShiftRows
  wire [31:0] sr0 = {sw0[31:24], sw1[23:16], sw2[15:8],  sw3[7:0]};
  wire [31:0] sr1 = {sw1[31:24], sw2[23:16], sw3[15:8],  sw0[7:0]};
  wire [31:0] sr2 = {sw2[31:24], sw3[23:16], sw0[15:8],  sw1[7:0]};
  wire [31:0] sr3 = {sw3[31:24], sw0[23:16], sw1[15:8],  sw2[7:0]};

  // MixColumns
  function [7:0] gm2;
    input [7:0] b;
    gm2 = {b[6:0], 1'b0} ^ (b[7] ? 8'h1b : 8'h00);
  endfunction

  function [7:0] gm3;
    input [7:0] b;
    gm3 = gm2(b) ^ b;
  endfunction

  function [31:0] mixw;
    input [31:0] w;
    reg [7:0] b0, b1, b2, b3;
    reg [7:0] mb0, mb1, mb2, mb3;
    begin
      b0 = w[31:24]; b1 = w[23:16]; b2 = w[15:8]; b3 = w[7:0];
      mb0 = gm2(b0) ^ gm3(b1) ^ b2 ^ b3;
      mb1 = b0 ^ gm2(b1) ^ gm3(b2) ^ b3;
      mb2 = b0 ^ b1 ^ gm2(b2) ^ gm3(b3);
      mb3 = gm3(b0) ^ b1 ^ b2 ^ gm2(b3);
      mixw = {mb0, mb1, mb2, mb3};
    end
  endfunction

  wire [31:0] mc0 = mixw(sr0);
  wire [31:0] mc1 = mixw(sr1);
  wire [31:0] mc2 = mixw(sr2);
  wire [31:0] mc3 = mixw(sr3);

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      fsm_state <= IDLE;
      is_ready <= 0;
      round_reg <= 0;
      cycle_reg <= 0;
      state_reg <= 0;
      sw0 <= 0; sw1 <= 0; sw2 <= 0;
    end else begin
      if (next) begin
        fsm_state <= INIT_ROUND;
        state_reg <= block;
        round_reg <= 0;
        cycle_reg <= 0;
        is_ready <= 0;
      end else begin
        case (fsm_state)
          INIT_ROUND: begin
            state_reg <= state_reg ^ round_key;
            round_reg <= 1;
            cycle_reg <= 0;
            fsm_state <= MAIN_ROUND;
          end
          MAIN_ROUND: begin
            if (cycle_reg == 0) begin
              sw0 <= new_sboxw;
              cycle_reg <= 1;
            end else if (cycle_reg == 1) begin
              sw1 <= new_sboxw;
              cycle_reg <= 2;
            end else if (cycle_reg == 2) begin
              sw2 <= new_sboxw;
              cycle_reg <= 3;
            end else if (cycle_reg == 3) begin
              cycle_reg <= 0;
              if (round_reg == num_rounds) begin
                state_reg <= {sr0, sr1, sr2, sr3} ^ round_key;
                fsm_state <= DONE;
                is_ready <= 1;
              end else begin
                state_reg <= {mc0, mc1, mc2, mc3} ^ round_key;
                round_reg <= round_reg + 1;
              end
            end
          end
        endcase
      end
    end
  end

  // Dummy variables for testbench
  reg [1:0] enc_ctrl_reg = 0;
  wire [1:0] update_type = 0;
  reg [1:0] sword_ctr_reg = 0;
  reg [3:0] round_ctr_reg = 0;
  reg [31:0] block_w0_reg = 0;
  reg [31:0] block_w1_reg = 0;
  reg [31:0] block_w2_reg = 0;
  reg [31:0] block_w3_reg = 0;
  wire [127:0] block_new = 0;

  generate
    if (1) begin : round_logic
      wire [127:0] old_block = 0;
      wire [127:0] shiftrows_block = 0;
      wire [127:0] mixcolumns_block = 0;
      wire [127:0] addkey_init_block = 0;
      wire [127:0] addkey_main_block = 0;
      wire [127:0] addkey_final_block = 0;
    end
  endgenerate

endmodule

