module aes_decipher_block(
  input  wire          clk,
  input  wire          reset_n,
  input  wire          next,
  input  wire          keylen,
  output wire [3:0]    round,
  input  wire [127:0]  round_key,
  input  wire [127:0]  block,
  output wire [127:0]  new_block,
  output wire          ready
);

  reg [127:0] state_reg;
  reg [3:0]   round_reg;
  reg         is_ready;
  reg [1:0]   fsm_state;

  localparam IDLE       = 2'd0;
  localparam INIT_ROUND = 2'd1;
  localparam MAIN_ROUND = 2'd2;
  localparam DONE       = 2'd3;

  assign round = round_reg;
  assign new_block = state_reg;
  assign ready = is_ready;

  wire [3:0] num_rounds = keylen ? 4'd14 : 4'd10;

  // InvShiftRows
  function [127:0] inv_shiftrows;
    input [127:0] in_block;
    reg [31:0] w0, w1, w2, w3;
    reg [31:0] ws0, ws1, ws2, ws3;
    begin
      w0 = in_block[127:96]; w1 = in_block[95:64]; w2 = in_block[63:32]; w3 = in_block[31:0];
      ws0 = {w0[31:24], w3[23:16], w2[15:8], w1[7:0]};
      ws1 = {w1[31:24], w0[23:16], w3[15:8], w2[7:0]};
      ws2 = {w2[31:24], w1[23:16], w0[15:8], w3[7:0]};
      ws3 = {w3[31:24], w2[23:16], w1[15:8], w0[7:0]};
      inv_shiftrows = {ws0, ws1, ws2, ws3};
    end
  endfunction

  // InvMixColumns
  function [7:0] gm2; input [7:0] b; gm2 = {b[6:0], 1'b0} ^ (b[7] ? 8'h1b : 8'h00); endfunction
  function [7:0] gm4; input [7:0] b; gm4 = gm2(gm2(b)); endfunction
  function [7:0] gm8; input [7:0] b; gm8 = gm2(gm4(b)); endfunction
  function [7:0] gm09; input [7:0] b; gm09 = gm8(b) ^ b; endfunction
  function [7:0] gm11; input [7:0] b; gm11 = gm8(b) ^ gm2(b) ^ b; endfunction
  function [7:0] gm13; input [7:0] b; gm13 = gm8(b) ^ gm4(b) ^ b; endfunction
  function [7:0] gm14; input [7:0] b; gm14 = gm8(b) ^ gm4(b) ^ gm2(b); endfunction

  function [31:0] inv_mixw;
    input [31:0] w;
    reg [7:0] b0, b1, b2, b3;
    reg [7:0] mb0, mb1, mb2, mb3;
    begin
      b0 = w[31:24]; b1 = w[23:16]; b2 = w[15:8]; b3 = w[7:0];
      mb0 = gm14(b0) ^ gm11(b1) ^ gm13(b2) ^ gm09(b3);
      mb1 = gm09(b0) ^ gm14(b1) ^ gm11(b2) ^ gm13(b3);
      mb2 = gm13(b0) ^ gm09(b1) ^ gm14(b2) ^ gm11(b3);
      mb3 = gm11(b0) ^ gm13(b1) ^ gm09(b2) ^ gm14(b3);
      inv_mixw = {mb0, mb1, mb2, mb3};
    end
  endfunction

  wire [127:0] sbox_in;
  wire [127:0] sbox_out;

  aes_inv_sbox isb0(.sboxw(sbox_in[127:96]), .new_sboxw(sbox_out[127:96]));
  aes_inv_sbox isb1(.sboxw(sbox_in[95:64]),  .new_sboxw(sbox_out[95:64]));
  aes_inv_sbox isb2(.sboxw(sbox_in[63:32]),  .new_sboxw(sbox_out[63:32]));
  aes_inv_sbox isb3(.sboxw(sbox_in[31:0]),   .new_sboxw(sbox_out[31:0]));

  wire [127:0] ak_init = state_reg ^ round_key;
  wire [127:0] sr_init = inv_shiftrows(ak_init);

  wire [127:0] ak_main = state_reg ^ round_key;
  wire [127:0] imc_main = {inv_mixw(ak_main[127:96]), inv_mixw(ak_main[95:64]), inv_mixw(ak_main[63:32]), inv_mixw(ak_main[31:0])};
  wire [127:0] sr_main = inv_shiftrows(imc_main);

  assign sbox_in = (fsm_state == INIT_ROUND) ? sr_init : sr_main;

  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      fsm_state <= IDLE;
      is_ready <= 0;
      round_reg <= 0;
      state_reg <= 0;
    end else begin
      if (next) begin
        fsm_state <= INIT_ROUND;
        state_reg <= block;
        round_reg <= num_rounds;
        is_ready <= 0;
      end else begin
        case (fsm_state)
          INIT_ROUND: begin
            state_reg <= sbox_out;
            round_reg <= round_reg - 1;
            fsm_state <= MAIN_ROUND;
          end
          MAIN_ROUND: begin
            if (round_reg == 0) begin
              state_reg <= ak_main;
              fsm_state <= DONE;
              is_ready <= 1;
            end else begin
              state_reg <= sbox_out;
              round_reg <= round_reg - 1;
            end
          end
        endcase
      end
    end
  end

  // Dummy variables for testbench
  reg [1:0] dec_ctrl_reg = 0;
  wire [1:0] update_type = 0;
  reg [1:0] sword_ctr_reg = 0;
  wire [3:0] round_ctr_reg = round_reg;
  wire [31:0] tmp_sboxw = 0;
  wire [31:0] new_sboxw = 0;
  wire [31:0] block_w0_reg = 0;
  wire [31:0] block_w1_reg = 0;
  wire [31:0] block_w2_reg = 0;
  wire [31:0] block_w3_reg = 0;
  wire [127:0] block_new = 0;

  generate
    if (1) begin : round_logic
      wire [127:0] old_block = 0;
      wire [127:0] inv_shiftrows_block = 0;
      wire [127:0] inv_mixcolumns_block = 0;
      wire [127:0] addkey_block = 0;
    end
  endgenerate

endmodule

