module aes_core(
  input  wire          clk,
  input  wire          reset_n,
  input  wire          encdec,
  input  wire          init,
  input  wire          next,
  output wire          ready,
  input  wire [255:0]  key,
  input  wire          keylen,
  input  wire [127:0]  block,
  output wire [127:0]  result,
  output wire          result_valid
);

  wire [127:0] round_key;
  wire keymem_ready;
  wire [31:0] sboxw;
  wire [31:0] new_sboxw;

  wire [3:0] enc_round;
  wire [3:0] dec_round;

  wire [31:0] keymem_sboxw;
  wire [31:0] enc_sboxw;

  wire [3:0] round_mux = encdec ? enc_round : dec_round;

  aes_key_mem keymem(
    .clk(clk),
    .reset_n(reset_n),
    .key(key),
    .keylen(keylen),
    .init(init),
    .round(round_mux),
    .round_key(round_key),
    .ready(keymem_ready),
    .sboxw(keymem_sboxw),
    .new_sboxw(new_sboxw)
  );

  wire enc_next = next && encdec;
  wire dec_next = next && !encdec;

  wire [127:0] enc_result;
  wire enc_ready;

  aes_encipher_block enc_block(
    .clk(clk),
    .reset_n(reset_n),
    .next(enc_next),
    .keylen(keylen),
    .round(enc_round),
    .round_key(round_key),
    .sboxw(enc_sboxw),
    .new_sboxw(new_sboxw),
    .block(block),
    .new_block(enc_result),
    .ready(enc_ready)
  );

  wire [127:0] dec_result;
  wire dec_ready;

  aes_decipher_block dec_block(
    .clk(clk),
    .reset_n(reset_n),
    .next(dec_next),
    .keylen(keylen),
    .round(dec_round),
    .round_key(round_key),
    .block(block),
    .new_block(dec_result),
    .ready(dec_ready)
  );

  aes_sbox sbox(
    .sboxw(sboxw),
    .new_sboxw(new_sboxw)
  );

  assign sboxw = (op_reg == 1) ? keymem_sboxw : enc_sboxw;

  reg [1:0] op_reg; // 0: none, 1: init, 2: enc, 3: dec
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) op_reg <= 0;
    else if (init) op_reg <= 1;
    else if (enc_next) op_reg <= 2;
    else if (dec_next) op_reg <= 3;
  end

  assign ready = (op_reg == 1) ? keymem_ready :
                 (op_reg == 2) ? enc_ready :
                 (op_reg == 3) ? dec_ready : 1'b1;
  assign result = encdec ? enc_result : dec_result;
  assign result_valid = ready;

endmodule

