    $display("*** TC %0d ECB mode test started.", tc_number);
    tc_ctr = tc_ctr + 1;

    init_key(key, key_length);
    write_block(block);
    dump_dut_state();

    write_word(ADDR_CONFIG, (8'h00 + (key_length << 1)+ encdec));
    write_word(ADDR_CTRL, 8'h02);

    #(100 * CLK_PERIOD);

    read_result();

  //----------------------------------------------------------------
  // Device Under Test.
  //----------------------------------------------------------------
  aes dut(
           .clk(tb_clk),
           .reset_n(tb_reset_n),
           .cs(tb_cs),
           .we(tb_we),
           .address(tb_address),
           .write_data(tb_write_data),
           .read_data(tb_read_data)
          );


--
    end
  endtask // dump_dut_state


  //----------------------------------------------------------------
  // reset_dut()
  //
  // Toggle reset to put the DUT into a well known state.
  //----------------------------------------------------------------
  task reset_dut;
    begin
      $display("*** Toggle reset.");
      tb_reset_n = 0;

      #(2 * CLK_PERIOD);
      tb_reset_n = 1;
--
      $dumpfile("tb_aes.vcd");
      $dumpvars(0, tb_aes);

      init_sim();
      dump_dut_state();
      reset_dut();
      dump_dut_state();

      aes_test();

      display_test_results();

      $display("");
      $display("   -= Testbench for AES completed =-");
      $display("    ===============================");
      $display("");

task dump_dut_state;
  begin
    $display("cycle: 0x%016x", cycle_ctr);
    $display("State of DUT");
    $display("------------");
    $display("ctrl_reg:   init   = 0x%01x, next   = 0x%01x", dut.init_reg, dut.next_reg);
    $display("config_reg: encdec = 0x%01x, length = 0x%01x ", dut.encdec_reg, dut.keylen_reg);
    $display("");

    $display("block: 0x%08x, 0x%08x, 0x%08x, 0x%08x",
             dut.block_reg[0], dut.block_reg[1], dut.block_reg[2], dut.block_reg[3]);
    $display("");

  end
endtask // dump_dut_state


//----------------------------------------------------------------
// reset_dut()
//
// Toggle reset to put the DUT into a well known state.

  task dump_dut_state;
    begin
      $display("cycle: 0x%016x", cycle_ctr);
      $display("State of DUT");
      $display("------------");
      $display("ctrl_reg:   init   = 0x%01x, next   = 0x%01x", dut.init_reg, dut.next_reg);
      $display("config_reg: encdec = 0x%01x, length = 0x%01x ", dut.encdec_reg, dut.keylen_reg);
      $display("");

      $display("block: 0x%08x, 0x%08x, 0x%08x, 0x%08x",
               dut.block_reg[0], dut.block_reg[1], dut.block_reg[2], dut.block_reg[3]);
      $display("");

    end
  endtask // dump_dut_state

--


  //----------------------------------------------------------------
  // write_block()
  //
  // Write the given block to the dut.
  //----------------------------------------------------------------
  task write_block(input [127 : 0] block);
    begin
      write_word(ADDR_BLOCK0, block[127  :  96]);
      write_word(ADDR_BLOCK1, block[95   :  64]);
--


  //----------------------------------------------------------------
  // read_result()
  //
  // Read the result block in the dut.
  //----------------------------------------------------------------
  task read_result;
    begin
      read_word(ADDR_RESULT0);
      result_data[127 : 096] = read_data;

arguments.content:
module aes(
  input  wire          clk,
  input  wire          reset_n,
  input  wire          cs,
  input  wire          we,
  input  wire [7 :0]   address,
  input  wire [31 :0]  write_data,
  output wire [31 :0]  read_data
);

  // Core interface
  reg          init_reg;
  reg          next_reg;
  reg          encdec_reg;
  reg          keylen_reg;
  reg  [255:0] key_reg;

  reg  [31:0]  block_reg [0:3];
  wire [127:0] block = {block_reg[0], block_reg[1], block_reg[2], block_reg[3]};

  wire         core_ready;
  wire [127:0] core_result;
  wire         core_valid;

  aes_core core (
    .clk(clk),
    .reset_n(reset_n),
    .encdec(encdec_reg),
    .init(init_reg),
    .next(next_reg),
    .ready(core_ready),
    .key(key_reg),
    .keylen(keylen_reg),
    .block(block),
    .result(core_result),
    .result_valid(core_valid)
  );

  // Read logic
  reg [31:0] tmp_read_data;
  assign read_data = tmp_read_data;

  always @(*) begin
    tmp_read_data = 32'h0;
    if (cs && !we) begin
      case (address)
        8'h00: tmp_read_data = 32'h61657320; // "aes "
        8'h01: tmp_read_data = 32'h20202020; // "    "
        8'h02: tmp_read_data = 32'h302e3531; // "0.51"
        8'h08: tmp_read_data = {30'h0, next_reg, init_reg};
        8'h09: tmp_read_data = {30'h0, core_valid, core_ready};
        8'h0a: tmp_read_data = {30'h0, keylen_reg, encdec_reg};
        8'h10: tmp_read_data = key_reg[255:224];
        8'h11: tmp_read_data = key_reg[223:192];
        8'h12: tmp_read_data = key_reg[191:160];
        8'h13: tmp_read_data = key_reg[159:128];
        8'h14: tmp_read_data = key_reg[127:96];
        8'h15: tmp_read_data = key_reg[95:64];
        8'h16: tmp_read_data = key_reg[63:32];
        8'h17: tmp_read_data = key_reg[31:0];
        8'h20: tmp_read_data = block_reg[0];
        8'h21: tmp_read_data = block_reg[1];
        8'h22: tmp_read_data = block_reg[2];
        8'h23: tmp_read_data = block_reg[3];
        8'h30: tmp_read_data = core_result[127:96];
        8'h31: tmp_read_data = core_result[95:64];
        8'h32: tmp_read_data = core_result[63:32];
        8'h33: tmp_read_data = core_result[31:0];
      endcase
    end
  end

  // Write logic
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
      init_reg <= 0;
      next_reg <= 0;
      encdec_reg <= 0;
      keylen_reg <= 0;
      key_reg <= 0;
      block_reg[0] <= 0; block_reg[1] <= 0; block_reg[2] <= 0; block_reg[3] <= 0;
    end else begin
      init_reg <= 0;
      next_reg <= 0;
      if (cs && we) begin
        case (address)
          8'h08: begin
            init_reg <= write_data[0];
            next_reg <= write_data[1];
          end
          8'h0a: begin
            encdec_reg <= write_data[0];
            keylen_reg <= write_data[1];
          end
          8'h10: key_reg[255:224] <= write_data;
          8'h11: key_reg[223:192] <= write_data;
          8'h12: key_reg[191:160] <= write_data;
          8'h13: key_reg[159:128] <= write_data;
          8'h14: key_reg[127:96]  <= write_data;
          8'h15: key_reg[95:64]   <= write_data;
          8'h16: key_reg[63:32]   <= write_data;
          8'h17: key_reg[31:0]    <= write_data;
          8'h20: block_reg[0]     <= write_data;
          8'h21: block_reg[1]     <= write_data;
          8'h22: block_reg[2]     <= write_data;
          8'h23: block_reg[3]     <= write_data;
        endcase
      end
    end
  end

endmodule
